exercise.solution:
const pool = new Pool({
  password: process.env.DB_PASSWORD,
});

app.get('/users', async (req, res) => {
  const { rows } = await pool.query(
    'SELECT id, email, name FROM users WHERE email = $1',
    [req.query.email]
  );
  res.json(rows);
});
